"use client";

import { useRef, useState } from "react";
import { ChatComposer } from "@/components/chat-composer";
import { SafeMarkdown } from "@/components/markdown";
import { analyticsApi } from "@/lib/api/analytics";
import { ApiError } from "@/lib/api/client";
import type { AnalystRun, PublicRunEvent } from "@/types/analytics";
import { statusFromEvent } from "./status";

type Message = { role: "user" | "assistant"; content: string };

export function Workbench() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [status, setStatus] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const source = useRef<EventSource | null>(null);
  const terminalRun = useRef<string | null>(null);
  const finishing = useRef(false);

  const finish = async (runId: string) => {
    if (finishing.current) return;
    finishing.current = true;
    let run: AnalystRun | undefined;
    // The completion trace event is recorded just before the UI run coordinator
    // stores its final response. Briefly retry so SSE never races the status API.
    for (let attempt = 0; attempt < 8; attempt += 1) {
      run = await analyticsApi.getRun(runId);
      if (run.status !== "running") break;
      await new Promise((resolve) => window.setTimeout(resolve, 100));
    }
    if (!run) throw new Error("The run result was unavailable.");
    if (run.status === "completed" && run.final_response) setMessages((current) => [...current, { role: "assistant", content: run.final_response! }]);
    else setError(run.error ?? "The analyst run ended without an answer.");
    setStatus(null); source.current?.close(); source.current = null;
  };
  const submit = async (message: string) => {
    terminalRun.current = null; finishing.current = false;
    setError(null); setStatus("Analyzing…"); setMessages((current) => [...current, { role: "user", content: message }]);
    try {
      const created = await analyticsApi.createRun({ message });
      source.current = analyticsApi.connect(created.run_id, (event: PublicRunEvent) => {
        setStatus(statusFromEvent(event));
        if (event.type === "run.completed") { terminalRun.current = created.run_id; void finish(created.run_id); }
        if (event.type === "run.failed") { terminalRun.current = created.run_id; setError(typeof event.data.error === "string" ? event.data.error : "The analyst run failed."); setStatus(null); source.current?.close(); }
      }, () => {
        // EventSource reports a completed server-closed SSE connection as an error.
        if (terminalRun.current === created.run_id) return;
        setError("The progress stream disconnected. Checking the run status…"); void finish(created.run_id).catch(() => setStatus(null));
      });
    } catch (cause) { setStatus(null); setError(cause instanceof ApiError ? cause.message : "Unable to start the analyst run."); }
  };
  const newConversation = () => { source.current?.close(); terminalRun.current = null; finishing.current = false; setMessages([]); setStatus(null); setError(null); };
  return <main className="workbench">
    <aside className="sidebar"><div><span className="eyebrow">WORKBENCH</span><h1>AI Data Analyst</h1></div><button className="new-conversation" onClick={newConversation}>＋ New conversation</button><section><p>RECENT</p><span className="muted">History will appear here when it is available.</span></section></aside>
    <section className="conversation"><header><div><span className="eyebrow">ANALYSIS SESSION</span><h2>AI Data Analyst</h2></div><span className="connection">● Backend connected</span></header>
      <div className="messages" aria-live="polite">{messages.length === 0 && !status && <div className="empty"><h3>Ask a question about your data</h3><p>Try investigating revenue changes, customer behavior, conversion, or operational performance.</p></div>}
      {messages.map((message, index) => <article className={`message ${message.role}`} key={index}>{message.role === "assistant" ? <SafeMarkdown content={message.content} /> : message.content}</article>)}
      {status && <div className="progress"><span className="spinner" />{status}</div>}
      {error && <div className="error" role="alert">{error}</div>}</div>
      <ChatComposer onSubmit={submit} disabled={Boolean(status)} />
    </section>
  </main>;
}
